package org.apache.commons.math.analysis.solvers;

import java.io.*;
import java.math.*;
import java.util.*;
import org.apache.commons.math.FunctionEvaluationException;
import org.apache.commons.math.MathRuntimeException;
import org.apache.commons.math.MaxIterationsExceededException;
import org.apache.commons.math.analysis.UnivariateRealFunction;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

public class BrentSolver_solve_TriageGen1Test {

    private BrentSolver solver;

    @Before
    public void setUp() {
        solver = new BrentSolver();
    }

    /**
     * Tests the case where the initial guess is already a root.
     * Covers: Math.abs(yInitial) <= functionValueAccuracy
     */
    @Test
    public void testSolve_InitialIsRoot() throws MaxIterationsExceededException, FunctionEvaluationException {
        // f(x) = x - 2, root is 2. Initial guess is 2.
        UnivariateRealFunction f = x -> x - 2;
        double result = solver.solve(f, 0.0, 5.0, 2.0);
        assertEquals(2.0, result, 1e-10);
    }

    /**
     * Tests the case where the minimum endpoint is already a root.
     * Covers: yInitial * yMin < 0 is false AND Math.abs(yMin) <= functionValueAccuracy
     */
    @Test
    public void testSolve_MinIsRoot() throws MaxIterationsExceededException, FunctionEvaluationException {
        // f(x) = x, root is 0. Min is 0. Initial is 1.
        // yInitial = 1, yMin = 0.
        UnivariateRealFunction f = x -> x;
        double result = solver.solve(f, 0.0, 5.0, 1.0);
        assertEquals(0.0, result, 1e-10);
    }

    /**
     * Tests the case where the initial guess and min bracket the root.
     * Covers: yInitial * yMin < 0
     */
    @Test
    public void testSolve_InitialAndMinBracket() throws MaxIterationsExceededException, FunctionEvaluationException {
        // f(x) = x - 1, root is 1. 
        // min=0 (y=-1), initial=2 (y=1). 
        // Wait, yInitial * yMin = 1 * -1 = -1 < 0.
        UnivariateRealFunction f = x -> x - 1;
        double result = solver.solve(f, 0.0, 5.0, 2.0);
        // Note: The code logic for yInitial * yMin < 0 calls a recursive solve with specific bounds.
        // We verify it finds the root 1.0.
        assertEquals(1.0, result, 1e-10);
    }

    /**
     * Tests the case where the maximum endpoint is already a root.
     * Covers: yInitial * yMin < 0 is false, yMin is not root, Math.abs(yMax) <= functionValueAccuracy
     */
    @Test
    public void testSolve_MaxIsRoot() throws MaxIterationsExceededException, FunctionEvaluationException {
        // f(x) = x - 5, root is 5. Max is 5. Initial is 1.
        // yInitial = -4, yMin = -5, yMax = 0.
        UnivariateRealFunction f = x -> x - 5;
        double result = solver.solve(f, 0.0, 5.0, 1.0);
        assertEquals(5.0, result, 1e-10);
    }

    /**
     * Tests the case where the initial guess and max bracket the root.
     * Covers: yInitial * yMin < 0 is false, yMin is not root, yInitial * yMax < 0
     */
    @Test
    public void testSolve_InitialAndMaxBracket() throws MaxIterationsExceededException, FunctionEvaluationException {
        // f(x) = x - 3, root is 3.
        // min=0 (y=-3), initial=4 (y=1), max=5 (y=2).
        // yInitial * yMin = 1 * -3 = -3 < 0 -> This triggers the FIRST if block (Initial/Min).
        // To trigger the SECOND if (Initial/Max), we need yInitial * yMin > 0.

        // Let's adjust: min=0 (y=-3), initial=1 (y=-2), max=5 (y=2).
        // yInitial = -2, yMin = -3. yInitial * yMin = 6 (> 0).
        // yMax = 2. yInitial * yMax = -4 (< 0).
        UnivariateRealFunction f = x -> x - 3;
        double result = solver.solve(f, 0.0, 5.0, 1.0);
        assertEquals(3.0, result, 1e-10);
    }

    /**
     * Tests the full Brent algorithm path.
     * Covers: All previous 'if' conditions are false.
     */
    @Test
    public void testSolve_FullBrentAlgorithm() throws MaxIterationsExceededException, FunctionEvaluationException {
        // f(x) = (x-2)(x-4) is not good because we need a sign change for Brent.
        // Let's use f(x) = x^2 - 4, roots are -2, 2.
        // min=-3 (y=5), max=3 (y=5), initial=0 (y=-4).
        // yInitial = -4. yMin = 5. yMax = 5.
        // yInitial * yMin = -20 (< 0) -> This hits the first if block.

        // To hit the FINAL else (Full Brent), we need:
        // 1. yInitial is not root.
        // 2. yMin is not root.
        // 3. yInitial * yMin > 0 (Initial and Min same side)
        // 4. yMax is not root.
        // 5. yInitial * yMax > 0 (Initial and Max same side)
        // BUT the Brent algorithm requires the interval [min, max] to bracket the root (yMin * yMax < 0).

        // Let's try: f(x) = x - 2. Root = 2.
        // min = 0 (y=-2), max = 4 (y=2), initial = 1 (y=-1).
        // yInitial = -1, yMin = -2 -> yInitial * yMin = 2 (> 0).
        // yMax = 2. yInitial * yMax = -2 (< 0). -> This hits the SECOND if block.

        // The only way to hit the final solve(...) is if the logic bypasses the brackets.
        // However, the Brent algorithm implementation in Commons Math typically requires 
        // the interval to bracket the root. Let's provide a standard case that hits the final call.

        // If yInitial * yMin > 0 AND yInitial * yMax < 0, it hits the second if.
        // If yInitial * yMin < 0, it hits the first if.
        // To hit the final line: yInitial * yMin > 0 AND yInitial * yMax > 0.
        // But if yMin and yMax have same sign as yInitial, they don't bracket the root.
        // The Brent algorithm is then called on [min, yMin, max, yMax, initial, yInitial].

        UnivariateRealFunction f = x -> x - 2;
        // min=3 (y=1), max=4 (y=2), initial=5 (y=3).
        // yInitial=3, yMin=1, yMax=2.
        // yInitial*yMin=3, yInitial*yMax=6. All conditions false.
        double result = solver.solve(f, 3.0, 4.0, 5.0);
        // This will likely throw MaxIterationsExceededException because no root is bracketed,
        // which is a valid path to test.
        try {
            solver.solve(f, 3.0, 4.0, 5.0);
        } catch (MaxIterationsExceededException e) {
            // Expected
        }
    }
}
